public int[] ReverseExtraArray(int[] arr)
{
    int n = arr.Length;
    int[] result = new int[n];
    for (int i = 0; i < n; i++)
        result[i] = arr[n - 1 - i];
    return result;
}

public void ReverseInPlace(int[] arr)
{
    int left = 0, right = arr.Length - 1;
    while (left < right)
    {
        int temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}
